 public function testMugAndPosterFromSupplierSelectionToHeldEtsyExportWithoutNetwork():void{
  PortalAccessFixture::enroll();$calls=0;$deny=static function()use(&$calls){++$calls;throw new RuntimeException('No external request allowed');};add_filter('pre_http_request',$deny);
  try{foreach(['mug'=>[5,7,9,'DG2-001','fl-03',2475,1155],'poster'=>[6,8,10,'DG2-002','fl-04',2418,3018]] as $family=>[$b,$p,$v,$concept,$fixture,$w,$h]){
   $start=$this->call(['operation'=>'supplier_start','snapshot_id'=>$this->snapshot(),'concept_id'=>$concept,'product_family'=>$family,'blueprint_id'=>(string)$b,'provider_id'=>(string)$p,'variant_id'=>(string)$v]);$link=['supplier_workflow_hash'=>$start['supplier_workflow_hash']];
   $research=(new DigiForge\Research\CommercialResearchRepository())->read('personalized_pod',$start['hash'])['record']['research'];$research['sources'][]=['id'=>'buyer_notes','kind'=>'buyer_intent','url'=>'https://example.invalid/isolated-review','observed_at'=>'2026-11-05T00:00:00Z','excerpt'=>'Synthetic buyer-intent observation, not actual demand','provenance'=>'Isolated test only'];
   $revised=$this->call($link+['operation'=>'revise_research','workflow_hash'=>$start['hash'],'title'=>$research['title'],'product_family'=>$family,'sources'=>$research['sources'],'note'=>'Add manually observed buyer intent']);$start['hash']=$revised['hash'];$bad=$research['sources'];$bad[0]['url']='https://foreign.invalid/';self::assertWPError((new Shop2ProductWorkflowPanel())->process($link+['operation'=>'revise_research','workflow_hash'=>$start['hash'],'title'=>$research['title'],'product_family'=>$family,'sources'=>$bad,'note'=>'Cannot replace supplier source','shop_key'=>'personalized_pod']));
   $f=json_decode(file_get_contents(__DIR__.'/../fixtures/research/commercial-research.json'),true);$response=$f['response'];foreach($response['scores'] as &$score)$score=null;unset($score);foreach($response['concepts'] as &$c)$c['source_ids']=['supplier_catalog'];unset($c);
   $r=$this->call($link+['operation'=>'concepts','workflow_hash'=>$start['hash'],'method'=>'manual','response_json'=>wp_json_encode($response)]);
   $selected=$this->call($link+['operation'=>'select','workflow_hash'=>$r['hash'],'concept'=>'1']);$ctx=$link+['workflow_hash'=>$selected['hash']];
   $a=$this->call($ctx+['operation'=>'design_approve_concept','sources_reviewed'=>'1','buyer_intent_reviewed'=>'1','gifting_occasion_reviewed'=>'1','note'=>'Synthetic isolated review; no measured market demand']);
   $spec=$this->call($ctx+['operation'=>'design_prepare','factory_hash'=>$a['design_factory_hash'],'profile'=>$family==='mug'?'fl03_mug_11oz':'fl04_poster_8x10','layout_notes'=>'Original art outside native reservation','typography'=>'Licensed type','font_license_reference'=>'Synthetic license evidence','palette'=>'#123456,#ffffff','asset_requirements'=>'Original SVG','native_regions_json'=>wp_json_encode([['name'=>'names','kind'=>'text','x'=>500,'y'=>400,'width'=>1400,'height'=>300]])]);
   $asset=$this->call($ctx+['operation'=>'design_import','factory_hash'=>$spec['design_factory_hash'],'svg'=>file_get_contents(__DIR__.'/../fixtures/design-factory/'.$family.'-original.svg'),'rasters_json'=>'[]','rights_note'=>'Synthetic original artwork','source_note'=>'Isolated manual import']);
   $approved=$this->call($ctx+['operation'=>'design_review','factory_hash'=>$asset['design_factory_hash'],'decision'=>'APPROVE','note'=>'Synthetic isolated human review','confirm'=>'1']+array_fill_keys(DesignFactoryContract::REVIEW_CRITERIA,'1'));
   for($i=1;$i<=5;$i++)$this->call($ctx+['operation'=>'mockup_import','factory_hash'=>$approved['design_factory_hash'],'png_base64'=>base64_encode($this->png($i)),'note'=>'Synthetic isolated mockup '.$i]);
   $e=json_decode(file_get_contents(__DIR__.'/../fixtures/product-packages/'.$fixture.'.json'),true);
   $e['template']=['template_id'=>'supplier-'.$family,'template_version'=>1,'supplier'=>'printify','provider_blueprint_id'=>$b,'provider_id'=>$p,'variant_ids'=>[$v],'personalization_pipeline'=>'PRINTIFY_NATIVE','personalization_engine'=>'MANUAL_DECLARATION','template_status'=>'DRAFT','print_areas'=>[['position'=>'front','decoration_method'=>'sublimation','width_px'=>$w,'height_px'=>$h]]];
   $e['specification']['native_fields']=[['layer'=>'names','type'=>'TEXT','required'=>true,'max_characters'=>30,'provider_field_id'=>null]];
   $pc=$ctx+['factory_hash'=>$approved['design_factory_hash']];$pkg=$this->call($pc+['operation'=>'package_prepare','evidence_mode'=>'import','evidence_json'=>wp_json_encode($e)]);
   $post=$pc+['operation'=>'package_export','package_hash'=>$pkg['package_hash'],'confirm'=>'1','shop_key'=>'personalized_pod'];self::assertWPError((new Shop2ProductWorkflowPanel())->process($post));
   $this->call($pc+['operation'=>'package_decide','package_hash'=>$pkg['package_hash'],'decision'=>'APPROVE','note'=>'Held package review only, production remains blocked','confirm'=>'1']);
   $out=$this->call($post);$export=json_decode($out['package_export'],true);self::assertSame($b,$export['supplier_selection']['blueprint_id']);self::assertSame($concept,$export['supplier_selection']['concept_id']);self::assertSame('UNSUBMITTED_LOCAL_WORKSHEET',$export['etsy_draft']['state']);self::assertSame($e['listing']['title'],$export['etsy_draft']['fields']['title']);self::assertFalse($export['external_execution_authorized']);self::assertFalse($export['etsy_draft']['publishing_authorized']);self::assertNotContains('FIVE_DISTINCT_REVIEWED_MOCKUPS_REQUIRED',$export['remaining_gates']);self::assertCount(5,$export['etsy_draft']['media']);self::assertContains('SUPPLIER_MOCKUP_AUTHENTICITY_UNVERIFIED',$export['remaining_gates']);
   $bundle=$this->call($pc+['operation'=>'package_bundle','package_hash'=>$pkg['package_hash'],'confirm'=>'1']);$tmp=tempnam(sys_get_temp_dir(),'df-review-bundle-');file_put_contents($tmp,$bundle['package_bundle']);$zip=new ZipArchive();self::assertTrue($zip->open($tmp,ZipArchive::CHECKCONS));$manifest=json_decode($zip->getFromName('manifest.json'),true);foreach($manifest['files'] as $file)self::assertSame($file['sha256'],hash('sha256',$zip->getFromName($file['path'])));self::assertSame(file_get_contents(__DIR__.'/../fixtures/design-factory/'.$family.'-original.svg'),$zip->getFromName('artwork/fixed-artwork.svg'));self::assertFalse(json_decode($zip->getFromName('held-package.json'),true)['external_execution_authorized']);$zip->close();unlink($tmp);
   $_GET=['df_supplier_workflow'=>$start['supplier_workflow_hash'],'df_research_version'=>$selected['hash'],'df_factory_version'=>$approved['design_factory_hash'],'df_package_version'=>$pkg['package_hash']];ob_start();(new Shop2ProductWorkflowPanel())->render(home_url('/'));$html=ob_get_clean();self::assertStringContainsString('digiforge_shop2_product_workflow',$html);self::assertStringContainsString('Held product package',$html);self::assertStringContainsString('Native personalization',$html);self::assertStringNotContainsString('name="action" value="digiforge_commercial_research"',$html);$_GET=[];
   $e['template']['provider_id']=999;self::assertWPError((new Shop2ProductWorkflowPanel())->process($pc+['operation'=>'package_prepare','evidence_mode'=>'import','evidence_json'=>wp_json_encode($e),'shop_key'=>'personalized_pod']));
  }self::assertSame(0,$calls);}finally{remove_filter('pre_http_request',$deny);}
 }
 public function testUnsignedAdminAndViewerCannotStartWorkflow():void{self::assertTrue(class_exists(Shop2ProductWorkflowPanel::class));wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));self::assertWPError((new Shop2ProductWorkflowPanel())->process(['operation'=>'supplier_start','shop_key'=>'personalized_pod']));$owner=PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);DigiForge\PortalAccess\Store::change($id,'Viewer',['personalized_pod'=>['research','personalized_pod','products','listings']],true,0,wp_generate_uuid4());PortalAccessFixture::login($id);DigiForge\PortalAccess\Session::start();self::assertWPError((new Shop2ProductWorkflowPanel())->process(['operation'=>'supplier_start','shop_key'=>'personalized_pod']));}
 public function testSnapshotReferenceCannotAdmitForeignOrCredentialQueryUrls():void{$url=add_query_arg(['df_view'=>'pod_personalized','df_shop'=>'personalized_pod','df_pi_snapshot'=>str_repeat('a',64)],set_url_scheme(home_url('/'),'https'));self::assertTrue(DigiForge\POD\Shop2ProductWorkflow::snapshotReference($url));foreach([$url.'&token=protected',$url.'&df_shop=personalized_pod',str_replace(parse_url($url,PHP_URL_HOST),'foreign.invalid',$url),$url.'#fragment'] as $bad)self::assertFalse(DigiForge\POD\Shop2ProductWorkflow::snapshotReference($bad));}
 private function png(int $shade):string{$chunk=static fn($t,$d)=>pack('N',strlen($d)).$t.$d.hash('crc32b',$t.$d,true);return "\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',8,8,8,2,0,0,0)).$chunk('IDAT',gzcompress(str_repeat("\x00".str_repeat(chr($shade)."\x22\x33",8),8))).$chunk('IEND','');}
 public function testCorruptMockupIsNotStored():void{PortalAccessFixture::enroll();self::assertTrue(method_exists(DigiForge\Research\DesignFactoryContract::class,'mockup'));$this->expectException(InvalidArgumentException::class);DigiForge\Research\DesignFactoryContract::mockup($this->png(1).'trailing');}
 public function testGeometryConflictsCrossWorkflowAndDisabledAccessFailClosed():void{
  $owner=PortalAccessFixture::enroll();$a=$this->call(['operation'=>'supplier_start','snapshot_id'=>$this->snapshot(),'concept_id'=>'DG2-001','product_family'=>'mug','blueprint_id'=>'5','provider_id'=>'7','variant_id'=>'9']);
  $b=$this->call(['operation'=>'supplier_start','snapshot_id'=>$this->snapshot(),'concept_id'=>'DG2-002','product_family'=>'poster','blueprint_id'=>'6','provider_id'=>'8','variant_id'=>'10']);$repo=new DigiForge\POD\Shop2ProductWorkflow();$link=$repo->read($a['supplier_workflow_hash']);
  self::assertWPError($repo->geometry($link,2476,1155));self::assertWPError($repo->context($link,$b['hash']));
  self::assertWPError((new Shop2ProductWorkflowPanel())->process(['operation'=>'assist','shop_key'=>'personalized_pod','supplier_workflow_hash'=>$a['supplier_workflow_hash'],'workflow_hash'=>$a['hash']]));
  $_GET=['df_shop'=>'digital'];ob_start();(new Shop2ProductWorkflowPanel())->render(home_url('/'));self::assertSame('',ob_get_clean());$_GET=[];
  $id=self::factory()->user->create(['role'=>'administrator']);DigiForge\PortalAccess\Store::change($id,'Operator',['personalized_pod'=>['research','personalized_pod','products']],true,0,wp_generate_uuid4());PortalAccessFixture::login($id);DigiForge\PortalAccess\Session::start();self::assertTrue(DigiForge\POD\Shop2ProductWorkflow::access());self::assertFalse(DigiForge\POD\Shop2ProductWorkflow::access(true));
  PortalAccessFixture::login($owner);DigiForge\PortalAccess\Session::start();$profile=DigiForge\PortalAccess\Store::read($id);DigiForge\PortalAccess\Store::change($id,'Operator',[],false,$profile['revision'],wp_generate_uuid4());PortalAccessFixture::login($id);self::assertFalse(DigiForge\POD\Shop2ProductWorkflow::access());
 }
